// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"all-time-high":{"slug":"all-time-high","cat":"basics","en":"All-time high (ATH)","contentLocale":"ja","term":"史上最高値（ATH）","aka":["ATH","過去最高値","All-time high"],"short":"史上最高値（ATH）とは、ある暗号資産がこれまでに記録した中で最も高い価格のことで、英語のAll-Time Highの略です。","body":["ATHは通常、取引所やデータサイトが集計した価格で表示されます。取引所ごとに一瞬の高値が異なるため、どの価格を最高値とするかは表示元によって少しずつ違います。また、円建てとドル建てでは為替の影響で、ATHを付けた時期がずれることもあります。",["価格がATHを更新すると、それより上で買った人がいないため、",["含み損","unrealized-pnl"],"を抱えた人の「戻り売り」が出にくく、上昇が勢いづくことがあると説明されます。一方で、注目が集まってFOMOが広がり、過熱しやすい局面でもあります。"],"「ATHからの下落率」は、銘柄の現在地を測る目安としてよく使われます。ただし、ATHから大きく下がっているからといって割安とは限りません。供給量の増加や需要の減少で、以前の高値に二度と戻らない銘柄も多くあります。"],"example":"例えば、ATHが4ドルだったトークンが現在1ドルなら、ATHから75%下落しています。ATHの4ドルで2,000ドル分（500枚）買った人の評価額は、現在500ドルです。一方、1ドルで500ドル分（500枚）を買った人は、価格が2ドルになれば評価額1,000ドルで利益が出ますが、ATHで買った人はその時点でもまだ1,000ドルの含み損を抱えています。","mistakes":["ATHから大きく下がっていることだけを理由に割安だと判断すること。","ATH更新のニュースを見て、計画なしに高値で飛びつくこと。","円建てとドル建てのATHを混同し、価格の位置を見誤ること。"],"faq":[{"q":"ATHとATLの違いは何ですか？","a":"ATHは史上最高値、ATL（All-Time Low）は史上最安値を指します。"},{"q":"ATHを更新した後は下がりますか？","a":"決まったパターンはありません。そのまま上昇が続く場合もあれば、すぐに大きく調整する場合もあります。"}],"title":"ATH（史上最高値）とは？意味と見方を解説","description":"暗号資産でよく使われるATH（史上最高値）の意味、ATHからの下落率の見方、高値更新時に気をつけたい点を解説します。","related":[["bull-market","強気相場（ブルマーケット）","強気相場（ブルマーケット）とは、価格が長期間にわたって上昇傾向を続け、市場参加者の間に楽観的な見方が広がっている相場のことです。"],["fomo","FOMO（フォーモ）","FOMOとは「Fear Of Missing Out」の略で、値上がりに乗り遅れることへの不安から、冷静な判断をせずに買ってしまう心理のことです。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"],["support-and-resistance","サポートライン・レジスタンスライン（支持線・抵抗線）","サポートライン・レジスタンスラインとは、過去に下落が止まりやすかった価格帯（支持線）と、上昇が止まりやすかった価格帯（抵抗線）をチャート上に示したものです。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"coin-margined-futures":{"slug":"coin-margined-futures","cat":"derivatives","en":"Coin-margined (inverse) futures","contentLocale":"ja","term":"コイン建て先物（インバース先物）","aka":["コイン建て","インバース先物","コインマージン先物","COIN-M"],"short":"コイン建て先物（インバース先物）とは、証拠金と損益をUSDTではなくBTCやETHなどのコインそのもので受け渡す先物契約で、契約サイズは米ドル建てで表されるのが一般的です。","body":[[["USDT建て先物","usdt-margined-futures"],"ではUSDTを証拠金にしますが、コイン建て先物ではBTCの契約ならBTCを証拠金として差し入れ、利益も損失もBTCで計算されます。1契約が100米ドル分などドル建てで決められているため、価格によって1契約に相当するBTCの枚数が変わります。この非線形の関係から「インバース」と呼ばれます。"],["コイン建ての特徴は、証拠金そのものが値動きする点です。",["ロング","long-and-short"],"を持つと、価格が上がれば先物の利益に加えて証拠金のBTCの価値も上がり、下がれば両方が下がります。一方、BTCを保有している人がコイン建てでショートすれば、手持ちのBTCをドル建てで固定する",["ヘッジ","hedging"],"として使えます。"],["マイナーや長期保有者が使うことが多く、BTCのまま損益を受け取りたい人に向いています。ただし計算がUSDT建てより直感的でないため、取引画面の損益表示や",["清算価格","liquidation-price"],"の計算を確認してから取引してください。"]],"example":"BTCが50,000ドルのとき、1契約100ドルのコイン建て先物を100契約（1万ドル分）ロングしたとします。建てたときの価値は10,000÷50,000＝0.2 BTCです。BTCが62,500ドルに上がると、同じ1万ドル分は0.16 BTCになるため、利益は0.2−0.16＝0.04 BTCで、62,500ドル換算で2,500ドルです。BTCで受け取った利益自体も、その後の価格変動の影響を受けます。","mistakes":["コイン建てとUSDT建てで損益の計算方法が同じだと思い、ポジションサイズを誤る。","コイン建てでロングすると、証拠金のBTCの値下がりと先物の損失が同時に起きることを見落とす。","BTCを持っていない状態でコイン建てのショートを使い、ヘッジのつもりが単なる投機になっていることに気づかない。"],"faq":[{"q":"コイン建てとUSDT建てはどちらを選べばよいですか？","a":"損益をUSDTで管理したいならUSDT建て、BTCなどのコインのまま持ちたいならコイン建てが向いています。初心者には計算がわかりやすいUSDT建てが選ばれることが多いです。"},{"q":"なぜインバース先物と呼ばれるのですか？","a":"契約サイズがドル建てで、証拠金と損益がコイン建てのため、損益が価格の逆数に比例する形になるからです。"}],"title":"コイン建て先物（インバース先物）とは？仕組みと計算","description":"コイン建て先物（インバース先物）の仕組み、BTCで受け渡す証拠金と損益の計算方法、USDT建てとの違いやヘッジへの使い方を解説します。","related":[["usdt-margined-futures","USDT建て先物（リニア先物）","USDT建て先物（リニア先物）とは、証拠金と損益をステーブルコインのUSDTで計算する先物契約で、価格の変化と損益が比例するためわかりやすいのが特徴です。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["unrealized-pnl","含み損益（未実現損益）","含み損益（未実現損益）とは、まだ決済していないポジションについて、現在の価格で決済したと仮定した場合の利益または損失のことです。"],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"hedging":{"slug":"hedging","cat":"derivatives","en":"Hedging","contentLocale":"ja","term":"ヘッジ（リスクヘッジ）","aka":["リスクヘッジ","ヘッジング","hedging","両建て"],"short":"ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。","body":[[["暗号資産","cryptocurrency"],"で最も基本的なヘッジは、現物を持ったまま先物でショートを持つ方法です。価格が下がれば現物は損失になりますが、ショートで利益が出るため、合計の損失が小さくなります。逆に価格が上がれば、現物の利益の一部がショートの損失で相殺されます。ヘッジは利益を増やす方法ではなく、価格変動の影響を小さくする方法です。"],["全量をヘッジすれば価格の影響はほぼなくなり、半分だけヘッジすれば影響も半分になります。",["オプション","options"],"のプットを買う方法もあり、こちらはプレミアムを払う代わりに、上昇時の利益をそのまま残せます。"],["ヘッジにはコストがあります。先物では",["資金調達率","funding-rate"],"の支払い、手数料、清算を防ぐための証拠金管理が必要で、オプションではプレミアムがかかります。現物とヘッジ先が別の取引所にある場合、価格のずれや清算のリスクも考えなければなりません。"]],"example":["1 BTCを60,000 USDTで保有していて、短期的な下落に備えたいとします。BTC",["無期限先物","perpetual-futures"],"で0.5 BTC分のショートを60,000 USDTで建てました。BTCが54,000 USDTに下がると、現物の評価損は6,000 ",["USDT","usdt"],"、ショートの利益は（60,000−54,000）×0.5＝3,000 USDTで、合計の損失は3,000 USDTに半減します。BTCが66,000 USDTに上がった場合は、現物の利益6,000 USDTからショートの損失3,000 USDTを引いて、合計3,000 USDTの利益です。"],"mistakes":["ヘッジ用のショートに高いレバレッジをかけ、価格上昇時にショートだけが清算されてヘッジが外れる。","資金調達率や手数料などのヘッジのコストを計算に入れない。","現物とヘッジの数量をそろえず、どれだけ相殺されているかを把握していない。"],"faq":[{"q":"ヘッジすると損をしないのですか？","a":"ヘッジは損失を小さくする代わりに、利益も小さくします。また資金調達率や手数料などのコストがかかります。"},{"q":"現物を売る代わりにヘッジする理由は何ですか？","a":"現物を手放さずに一時的なリスクを抑えたい場合や、売却で税金などが発生するのを避けたい場合に使われます。課税の扱いは国によって異なります。"}],"title":"ヘッジとは？暗号資産でのリスクヘッジの方法","description":"暗号資産のヘッジ（リスクヘッジ）の意味、現物と先物ショートを組み合わせる方法、オプションでのヘッジ、コストと注意点を解説します。","related":[["short-selling","空売り（ショートセリング）","空売り（ショートセリング）とは、持っていない資産を先に売り、後で値下がりしたところで買い戻して差額を利益にする取引方法です。"],["perpetual-futures","無期限先物（パーペチュアル）","無期限先物（パーペチュアル）とは、満期日がなく、いつまでもポジションを持ち続けられる先物契約で、資金調達率（ファンディングレート）の支払いによって価格を現物価格に近づける仕組みです。"],["options","オプション取引（暗号資産オプション）","オプション取引とは、ある資産を将来の決められた日に、決められた価格（権利行使価格）で買う権利（コール）または売る権利（プット）を売買する取引です。"],["portfolio-margin","ポートフォリオマージン","ポートフォリオマージンとは、口座内のすべてのポジションをまとめて評価し、互いに打ち消し合うリスクを考慮して必要な証拠金を計算する方式です。"]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"現物と先物：買っているものは同じではない"},"coin":null,"tool":null,"cta":false},"options":{"slug":"options","cat":"derivatives","en":"Crypto options","contentLocale":"ja","term":"オプション取引（暗号資産オプション）","aka":["オプション","コールオプション","プットオプション","options"],"short":"オプション取引とは、ある資産を将来の決められた日に、決められた価格（権利行使価格）で買う権利（コール）または売る権利（プット）を売買する取引です。","body":["オプションの買い手は、プレミアムと呼ばれる代金を払って権利を手に入れます。満期に有利なら権利を行使し、不利なら放棄できるため、買い手の最大損失は支払ったプレミアムに限られます。反対に売り手はプレミアムを受け取る代わりに、相場が大きく動いたときに支払う義務を負い、損失が大きくなる可能性があります。",["コールは価格の上昇、プットは価格の下落で価値が上がります。現物を持っている人がプットを買えば値下がりに備える",["ヘッジ","hedging"],"になり、上昇時の利益はそのまま残せます。オプションの価格は、原資産の価格、権利行使価格、満期までの期間、そして",["ボラティリティ","volatility"],"（価格変動の大きさの予想）によって決まります。"],["暗号資産オプションは、Deribitが大きなシェアを持つほか、OKX、Bybit、Binanceなども提供しています。",["暗号資産","cryptocurrency"],"取引所の多くは満期日にだけ行使できるヨーロピアン型で、差金決済です。取引所の「",["デュアル投資","dual-investment"],"」などの商品も、内部ではオプションの売りを組み込んでいることがあります。"]],"example":["BTCが62,000 USDTのとき、権利行使価格65,000 ",["USDT","usdt"],"、満期1か月のコールオプションを1 BTC分、プレミアム1,500 USDTで買ったとします。満期にBTCが70,000 USDTなら、価値は70,000−65,000＝5,000 USDTで、プレミアムを引いた利益は3,500 USDTです。損益分岐点は65,000＋1,500＝66,500 USDTです。満期にBTCが65,000 USDT以下なら権利は無価値になり、損失は1,500 USDTで止まります。"],"mistakes":["オプションの売り手も買い手と同じく損失が限定されていると思い込む。","価格が予想どおりの方向に動いても、満期までに十分動かなければプレミアム分だけ損をすることを見落とす。","ボラティリティの低下でオプションの価格が下がり、相場が動かなくても損失が出ることを知らない。"],"faq":[{"q":"コールとプットの違いは何ですか？","a":"コールは決められた価格で買う権利、プットは決められた価格で売る権利です。コールは上昇時、プットは下落時に価値が上がります。"},{"q":"オプションの買い手の最大損失はいくらですか？","a":"支払ったプレミアムが最大損失です。売り手は受け取ったプレミアムを上回る損失が出る可能性があります。"}],"title":"暗号資産のオプション取引とは？コールとプットの基本","description":"暗号資産オプションの仕組み、コールとプットの違い、プレミアムと損益分岐点の計算、買い手と売り手のリスクの違いを解説します。","related":[["futures-contract","先物取引（先物契約）","先物取引とは、ある資産を将来の特定の時点に、あらかじめ決めた価格で売買することを約束する契約で、暗号資産では現物を持たずに価格変動の差額だけをやり取りするのが一般的です。"],["hedging","ヘッジ（リスクヘッジ）","ヘッジとは、保有している資産の値下がりなどのリスクを抑えるために、反対方向に動くポジションを持って損失を相殺する取引のことです。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"],["dual-investment","デュアル投資（Dual Investment）","デュアル投資とは、あらかじめ決めた価格（ターゲット価格）と期日を設定し、期日の価格に応じて元本と利息を暗号資産かステーブルコインのどちらかで受け取る仕組み商品です。"]],"lesson":null,"coin":null,"tool":"/topics/derivatives","cta":false},"custodial-wallet":{"slug":"custodial-wallet","cat":"wallets-security","en":"Custodial wallet","contentLocale":"ja","term":"カストディアルウォレット（管理型ウォレット）","aka":["カストディアル","管理型ウォレット","custodial wallet"],"short":"カストディアルウォレットとは、暗号資産の秘密鍵を取引所やサービス事業者が管理し、利用者はIDとパスワードなどでアカウントにログインして資産を使う形のウォレットです。","body":[[["暗号資産","cryptocurrency"],"取引所に入金した資産は、多くの場合カストディアルの状態です。",["秘密鍵","private-key"],"は取引所が持ち、利用者の残高は取引所の帳簿で管理されています。",["シードフレーズ","seed-phrase"],"を自分で保管する必要がなく、パスワードを忘れても",["本人確認","kyc"],"で復旧できるため、初心者にとって使いやすい形です。"],"一方で、資産を実際に動かせるかどうかは事業者次第です。取引所の破綻、ハッキング、出金停止、アカウントの凍結などがあれば、資産を引き出せなくなる可能性があります。「Not your keys, not your coins（鍵を持たなければ自分のコインではない）」という言葉は、このリスクを表しています。",["国によって、取引所に顧客資産の分別管理や",["コールドウォレット","cold-wallet"],"での保管を義務づけるルールがあります。日本では",["暗号資産交換業者","vasp"],"に、利用者の暗号資産の分別管理や、その大部分をコールドウォレットなどで管理することが求められています。海外の取引所では、プルーフ・オブ・リザーブ（準備金証明）で預かり資産の裏付けを公開しているところもあります。"]],"example":"ある取引所に1 BTCと3,000 USDTを預けているとします。画面にはこの残高が表示されますが、ブロックチェーン上ではそのBTCは取引所のアドレスにまとめて保管されています。取引所のプルーフ・オブ・リザーブで、利用者のBTC残高の合計が10万 BTC、取引所が保有するBTCが10.2万 BTCと示されていれば、準備率は102%です。ただしこれは負債全体や他の資産の状況までは示しません。","mistakes":["取引所の残高は自分のウォレットと同じで、取引所に何があっても安全だと思い込む。","使う予定のない多額の資産を、長期間すべて1つの取引所に置いたままにする。","二段階認証を設定せず、パスワードだけでアカウントを守る。"],"faq":[{"q":"カストディアルウォレットとノンカストディアルウォレットの違いは？","a":"カストディアルは事業者が秘密鍵を管理し、ノンカストディアルは自分で秘密鍵を管理します。前者は手軽で復旧しやすく、後者は自分の責任で完全に管理できます。"},{"q":"取引所に資産を置いておくのは危険ですか？","a":"取引所の破綻やハッキング、出金停止のリスクがあります。頻繁に取引する分だけを取引所に置き、長期保有分は自分で管理する人も多いです。"}],"title":"カストディアルウォレットとは？仕組みとリスク","description":"カストディアルウォレット（管理型ウォレット）の仕組み、取引所に資産を預けるメリットとリスク、ノンカストディアルとの違いを解説します。","related":[["non-custodial-wallet","ノンカストディアルウォレット（セルフカストディ）","ノンカストディアルウォレットとは、秘密鍵やシードフレーズを取引所などの第三者ではなく、利用者自身が管理する暗号資産ウォレットのことです。"],["centralized-exchange","中央集権型取引所（CEX）","中央集権型取引所（CEX）とは、運営会社が利用者の資産を預かり、注文の照合や入出金を管理する暗号資産取引所のことです。"],["proof-of-reserves","準備金証明（プルーフ・オブ・リザーブ）","準備金証明（PoR）とは、取引所が利用者から預かった暗号資産と同額以上の資産を実際に保有していることを、ブロックチェーン上のデータなどで示す仕組みです。"],["crypto-wallet","暗号資産ウォレット（仮想通貨ウォレット）","暗号資産ウォレットとは、暗号資産を送受信するための秘密鍵とアドレスを管理するアプリや機器のことで、コインそのものではなく、それを動かす鍵を保管しています。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"私のコインはどこ？取引所とウォレットの違い"},"coin":null,"tool":null,"cta":false},"on-chain-analysis":{"slug":"on-chain-analysis","cat":"onchain","en":"On-chain analysis","contentLocale":"ja","term":"オンチェーン分析","aka":["オンチェーンデータ分析","on-chain analysis"],"short":"オンチェーン分析とは、ブロックチェーン上に公開されている取引記録やアドレスの残高などのデータを集計し、資金の流れや市場参加者の行動を読み解く手法のことです。","body":[[["ブロックチェーン","blockchain"],"では、送金や残高が誰でも見られる形で記録されています。オンチェーン分析では、このデータから取引所への入出金、大口保有者（",["クジラ","whale"],"）の動き、",["アクティブアドレス数","active-addresses"],"、長期保有者の売買などを読み取ります。チャートだけを見るテクニカル分析とは違う角度から市場を観察できます。"],["代表的な指標には、",["取引所ネットフロー","exchange-netflow"],"、",["ステーブルコイン","stablecoin"],"の供給量、保有期間別の供給量、実現価格などがあります。分析ツールごとに",["アドレス","wallet-address"],"のラベル付けや計算方法が異なるため、同じ指標名でも数値が一致しないことがあります。"],"注意点は、オンチェーンデータはあくまで「何が起きたか」の記録であり、未来の価格を約束するものではないことです。取引所内部の売買はブロックチェーンに記録されないため、市場全体の一部しか見えていない点も理解しておきましょう。"],"example":"ある1週間で、主要取引所のBTC残高が合計で2,000,000 BTCから1,980,000 BTCに減ったとします。20,000 BTCが流出した計算で、一般には「売るために取引所へ入れる量より、引き出して保管する量が多い」と解釈されます。ただし同じ週に、ある取引所が10,000 BTCをコールドウォレットの別アドレスへ移しただけだった場合、そのアドレスにラベルが付いていなければ流出として数えられます。数字の半分が内部移動だった可能性もあるため、大口の動きは送金先も確認する必要があります。","mistakes":["ひとつの指標の変化だけを見て、すぐに売買の判断をしてしまう。","取引所の内部的なウォレット移動を、ユーザーの大量入金や出金と誤解する。","ツールごとにラベル付けや計算方法が違うことを知らず、異なるサイトの数値を直接比較する。"],"faq":[{"q":"オンチェーン分析で価格を予測できますか？","a":"需給の傾向をつかむ材料にはなりますが、価格を確実に予測できるものではありません。テクニカル分析やマクロ環境と組み合わせて、状況を理解するために使うのが一般的です。"},{"q":"オンチェーン分析は無料でできますか？","a":"ブロックエクスプローラーや無料の分析サイトで基本的な指標は確認できます。より細かい指標や過去データは有料ツールで提供されていることが多いです。"}],"title":"オンチェーン分析とは？意味と主な指標の読み方","description":"オンチェーン分析の意味、取引所ネットフローやアクティブアドレスなど主な指標、データを読むときの注意点を具体例で解説します。","related":[["exchange-netflow","取引所ネットフロー（取引所への流入・流出）","取引所ネットフローとは、一定期間に暗号資産取引所のウォレットへ入った量から出た量を差し引いた数値で、流入超か流出超かを示すオンチェーン指標です。"],["whale","クジラ（大口投資家）","クジラとは、特定の暗号資産を大量に保有し、その売買や送金が市場価格に影響を与えるほどの規模を持つ大口の投資家やアドレスのことです。"],["active-addresses","アクティブアドレス数","アクティブアドレス数とは、一定期間内に送金または受取の取引に関わったブロックチェーン上のアドレスの数で、ネットワークの利用状況を測るオンチェーン指標です。"],["block-explorer","ブロックエクスプローラー","ブロックエクスプローラーとは、ブロックチェーン上の取引、アドレスの残高、ブロックの情報を検索して閲覧できるウェブサービスのことです。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"grid-trading-bot":{"slug":"grid-trading-bot","cat":"exchange-features","en":"Grid trading bot","contentLocale":"ja","term":"グリッドトレードボット","aka":["グリッドボット","グリッド取引","grid trading bot"],"short":"グリッドトレードボットとは、設定した価格帯をいくつかの網目（グリッド）に分け、価格が下がれば買い、上がれば売る指値注文を自動で繰り返す取引ツールのことです。","body":["上限価格と下限価格、グリッドの本数を決めると、ボットがその間に等間隔で買い注文と売り注文を並べます。価格が1マス下がると買い、1マス上がるとその分を売る、という動きを繰り返し、小さな値幅を積み重ねて利益を狙います。",["グリッドボットが得意なのは、一定の範囲を上下するレンジ相場です。価格が範囲の上限を突き抜けると、手持ちのコインはすべて売られた状態になり、その後の上昇を取り逃します。逆に下限を割り込むと、コインを抱えたまま",["含み損","unrealized-pnl"],"が膨らみます。"],["現物のグリッドだけでなく、先物で",["レバレッジ","leverage"],"をかけたグリッドもあり、その場合は清算のリスクが加わります。取引所によって設定項目や手数料の扱いが異なるため、1回の利益幅が往復の手数料を上回るよう設定することが大切です。"]],"example":"BTCが50,000〜60,000 USDTの範囲で動くと考え、10本のグリッドで1,000 USDTを投入したとします。1マスは1,000 USDTの間隔です。価格が55,000から54,000に下がるとボットが約100 USDT分を買い、55,000に戻ると売ります。1回の値幅は約1.85%なので、約1.85 USDTの利益です。ここから往復の手数料0.2 USDTを引くと約1.65 USDTが残ります。しかし価格が45,000まで下がると、範囲外で買ったコインを抱えたまま取引が止まり、含み損が残ります。","mistakes":["強いトレンドが出ている相場で、狭い範囲のグリッドを設定してしまう。","グリッドの本数を増やしすぎて、1回あたりの利益が手数料に消えてしまう。","表示される年率換算の利回りを、そのまま将来の利益だと考えてしまう。"],"faq":[{"q":"グリッドボットは下落相場でも利益が出ますか？","a":"範囲内で上下を繰り返していれば小さな利益は出ますが、価格が下限を割り込むと含み損が膨らみます。下落トレンドが続く相場には向いていません。"},{"q":"グリッドの本数は何本が良いですか？","a":"決まった正解はありません。本数を増やすと取引回数は増えますが、1回の利益は小さくなるため、手数料を上回る幅になっているかを必ず確認してください。"}],"title":"グリッドトレードボットとは？仕組みと設定のコツ","description":"グリッドトレードボットの意味と仕組み、レンジ相場とトレンド相場での違い、グリッドの本数や手数料を考えた設定の注意点を解説します。","related":[["dollar-cost-averaging","ドルコスト平均法（DCA）","ドルコスト平均法（DCA）とは、価格に関係なく一定の金額を定期的に買い続けることで、購入タイミングを分散させる投資手法です。"],["copy-trading","コピートレード","コピートレードとは、取引所上で選んだ他のトレーダーの売買を、自分の口座で自動的に同じように再現する仕組みのことです。"],["volatility","ボラティリティ（価格変動率）","ボラティリティとは、価格がどれだけ大きく、どれだけ頻繁に変動するかを表す度合いのことで、暗号資産は株式や為替より高い傾向があります。"],["limit-order","指値注文","指値注文とは、売買したい価格を自分で指定し、その価格かそれより有利な価格になったときにだけ約定させる注文方法です。"]],"lesson":null,"coin":null,"tool":null,"cta":true}});
